def chain_of_tokens(sjn, nhy):
    tokens = []
    current = sjn
    for i in range(len(sjn)):
        if i == 0:
            current = nhy
        else:
            next_token = current[i-1]
            if next_token == 'd':
                current = nhy
            else:
                current = next_token
        tokens.append(current)
    return ','.join(tokens)
